import{z as o,x as l,o as e,c as h,q as B,j as s,D as t,d as E,s as i,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Carhart 四因子","description":"","frontmatter":{"title":"Carhart 四因子","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/carhart4.md","filePath":"quant/carhart4.md","lastUpdated":1791063341000}'),p={name:"quant/carhart4.md"};function m(d,a,F,R,C,c){const n=l("Mermaid");return e(),h("div",null,[a[2]||(a[2]=B('<h1 id="carhart-四因子" tabindex="-1">Carhart 四因子 <a class="header-anchor" href="#carhart-四因子" aria-label="Permalink to &quot;Carhart 四因子&quot;">​</a></h1><div class="epigraph"><p>共同基金业绩的持续性，大部分可以被股票的动量因子吸收；控制市场、规模、价值与一年期动量之后，所谓热手几乎消失。</p><footer>—— Carhart, On Persistence in Mutual Fund Performance, Journal of Finance, 1997</footer></div><p><a href="/quant/cma-investment">上一课</a>把投资收成五因子的第四条腿。<a href="/quant/ff3">Fama–French 三因子</a> 留下一块醒目的 α：<a href="/quant/momentum-wml">动量</a> 组合不能被 SMB 与 HML 解释。Carhart（1997）不是为了再写一篇异常论文，而是为了评估<strong>共同基金</strong>的业绩持续性。他把 Jegadeesh–Titman 的相对强度收成第四个因子 <strong>PR1YR</strong>（后来 French 数据库里的 WML/UMD），与 RMRF、SMB、HML 组成四因子模型，对基金超额收益做时间序列回归。结论改变了行业叙事：过去的赢家基金明年仍然好，主要是因为它们恰好持有了过去的赢家股票，而不是因为经理有可重复的选股技术。本篇写四因子的构造、它与三因子/五因子的分工，以及把基金 α 写成「技能」之前必须先过的那一关。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三因子在 1993 年已经能吸收不少按规模、B/M 排序的组合。它吸收不了按过去收益排序的组合：赢家减输家的 α 显著为正，且 HML 载荷常常为负——动量偏成长。若评价基金时只用三因子，一只重仓动量股的基金会显出持续正 α，看起来像技能。Carhart 要区分两种持续性：<strong>持仓暴露的持续性</strong>与<strong>残差技能的持续性</strong>。前者应当被一个可交易的动量因子拿走；后者才是费用、交易与选股真正留下的东西。</p><p>基金文献此前用 CAPM 或行业调整，发现「热手」：过去一年业绩好的基金随后仍然略好。问题是基准太薄。规模、价值、动量都是基金经理会系统性地倾斜的风格。不把它们放进右侧，α 只是风格的别名。四因子把这个问题写成可检验的回归，而不是写成对经理能力的修辞。</p><h3 id="pr1yr-不是当日的-12-个月收益" tabindex="-1">PR1YR 不是当日的 12 个月收益 <a class="header-anchor" href="#pr1yr-不是当日的-12-个月收益" aria-label="Permalink to &quot;PR1YR 不是当日的 12 个月收益&quot;">​</a></h3><p>Carhart 的动量因子是：按过去 11 个月收益（再滞后一个月）把股票分成三档，高减低，等权。滞后一个月是为了躲开短期反转与微观结构噪声，与 Jegadeesh–Titman 跳过最近一个月的精神一致，但断点、加权与持有期的细节与后来 French 的 2×3 价值加权 WML 并不相同。复制「Carhart 四因子」却去下载 French 的 MOM，α 的数值会对不上原文表格。评价当代基金时，行业默认已经换成 French 的 UMD；写历史对照必须声明是 1997 年的 PR1YR 还是今天的 UMD。</p><p><span class="marginnote">基金收益是费用后、投资者实际得到的。因子是纸上组合、费用前。正的四因子 α 已经扣过管理费；负 α 更常见，表示费用与交易没有被风格暴露之外的收益覆盖。不要拿纸上 WML 的夏普去和基金 α 比谁更能赚钱。</span></p><p><span class="marginnote">数字实例：一只基金年超额收益 6%。四因子回归给出市场载荷 \\(b=1.0\\)、动量载荷 \\(p=0.4\\)；当年市场超额 5%、动量溢价 6%。风格贡献约 \\(1.0\\times 5\\% + 0.4\\times 6\\% = 7.4\\%\\)，于是 \\(\\alpha \\approx 6\\% - 7.4\\% = -1.4\\%\\)——表面跑赢市场，实际是动量暴露在赚，经理反而没有覆盖费用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对基金或组合 \\(i\\)，</p> \\[R_{it}-R_{ft}=\\alpha_i+b_i\\mathrm{RMRF}_t+s_i\\mathrm{SMB}_t+h_i\\mathrm{HML}_t+p_i\\mathrm{PR1YR}_t+e_{it}. \\]<p>RMRF 是市场超额，SMB、HML 循 Fama–French 的 2×3。PR1YR 在原文里是等权的一年期动量多空。检验分两层。第一层：对按过去收益排序的<strong>股票</strong>组合，\\(\\alpha\\) 在三因子下显著，加入 PR1YR 后被吸收——说明第四个因子确实对着动量异常。第二层：对按过去业绩排序的<strong>基金</strong>组合，三因子 α 的持续性大部分消失，四因子 α 接近零，尤其是赢家基金一侧；输家基金一侧仍常留下负 α，与费用、周转和持有输家股票的成本一致。</p><p>构造上注意三点。基金组合要用持有期收益，避免看后偏。因子必须与基金同一市场、同一货币：用美股四因子去回归全球或 A 股基金，β 没有定价含义。动量因子的再平衡是月频的，基金持仓披露是季频的，回归里的 \\(p_i\\) 是协方差暴露，不是季报里「动量股占比」的同步读数；两者相关，但滞后与披露误差会使持仓加权的特征暴露与 β 不一致。</p><h3 id="持续性检验在做什么" tabindex="-1">持续性检验在做什么 <a class="header-anchor" href="#持续性检验在做什么" aria-label="Permalink to &quot;持续性检验在做什么&quot;">​</a></h3><p>把基金按 \\(t-1\\) 年的收益分成十分位，看 \\(t\\) 年的平均收益或 α。CAPM 下十分位单调；四因子下单调性塌缩。Carhart 还展示：赢家基金的高收益在很大程度上来自它们对 PR1YR 的正载荷，而载荷本身来自持仓里的赢家股。若把因子溢价当成「被动可复制的风格」，则热手不是技能。若有人拒绝动量是风险因子、坚持它是错误定价，四因子 α 接近零仍然有操作含义：投资者可以用便宜的动量暴露去复制那块持续性，不必为基金的管理费买单。模型在这里的角色是<strong>基准</strong>，不必先完成「风险还是误定价」的哲学判决。</p><p>后续文献用持仓数据直接算基金的特征暴露（Daniel、Grinblatt、Titman、Wermers 的 DGTW 特征调整是另一条路），与四因子回归互补：特征调整在截面上对齐，四因子在时间序列上对齐。两者都显示，费用前的毛持续性强于费用后，主动基金整体的净 α 为负或接近零。Carhart 的贡献是把动量这一块从「技能」里明确剔除。</p>',18)),(e(),s(A,null,{default:t(()=>[i(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF3%5B%22RMRF%20%2B%20SMB%20%2B%20HML%22%5D%20--%3E%20REG%5B%22%E5%9F%BA%E9%87%91%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%E5%9B%9E%E5%BD%92%22%5D%0A%20%20PR%5B%22PR1YR%20%2F%20WML%22%5D%20--%3E%20REG%0A%20%20REG%20--%3E%20A%5B%22%E5%9B%9B%E5%9B%A0%E5%AD%90%20%CE%B1%22%5D%0A%20%20PAST%5B%22%E8%BF%87%E5%8E%BB%E4%B8%80%E5%B9%B4%E5%9F%BA%E9%87%91%E4%B8%9A%E7%BB%A9%E6%8E%92%E5%BA%8F%22%5D%20--%3E%20Q%5B%22%E5%8D%81%E5%88%86%E4%BD%8D%E7%BB%84%E5%90%88%22%5D%0A%20%20Q%20--%3E%20REG%0A%20%20A%20--%3E%20CON%5B%22%E6%8C%81%E7%BB%AD%E6%80%A7%E6%98%AF%E5%90%A6%E4%BB%8D%E5%9C%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"股票动量为何存在，见 WML 条目：反应不足、趋势追逐、以及拥挤与强平造成的左尾。四因子并不需要在基金论文里重判这些机制。它只需要承认：动量是股票收益里一块稳定的共同变动，基金作为股票组合会继承这块暴露。经理可以「有技能地」去买动量——那是对风格的择时或选择——但一旦 \\(p_i\\) 进入回归，靠被动扛着赢家股过日子的那部分就被拿走了。真正剩下的 α 必须来自：选对了因子模型没写进去的股票、行业时机、费用节约、或样本噪声。",-1)),a[5]||(a[5]=r("p",null,[r("span",{class:"marginnote"},"术语翻译：「α 被因子吸收」的意思是——基金赚的钱里，凡是能用「买市场、买小盘、买便宜、买近期赢家」这类机械规则解释的部分，都不记作技能；只有规则解释不掉的残差才叫 α。吸收得越多，留给「热手」的解释空间越小。")],-1)),a[6]||(a[6]=r("p",null,"输家基金的负 α 更有结构含义。业绩差的基金往往费用高、周转高、规模不经济，并持有难以卖空、难以出清的输家股。四因子吸收了「输家股随后继续弱」的一部分，但吸收不了费用与交易损耗。因此持续性在底部比在顶部更顽固：差的可以持续地差，好的很难持续地好。这与事后看「去年冠军」的销售叙事正好相反。",-1)),(e(),s(A,null,{default:t(()=>[i(n,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22%E5%9F%BA%E9%87%91%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20ABS%5B%22%E5%9B%9B%E5%9B%A0%E5%AD%90%E5%8F%AF%E5%90%B8%E6%94%B6%EF%BC%9A%E5%B8%82%E5%9C%BA%2F%E8%A7%84%E6%A8%A1%2F%E4%BB%B7%E5%80%BC%2F%E5%8A%A8%E9%87%8F%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20FR%20--%3E%20FEE%5B%22%E8%B4%B9%E7%94%A8%E3%80%81%E5%91%A8%E8%BD%AC%E4%B8%8E%E4%BA%A4%E6%98%93%E6%8D%9F%E8%80%97%22%5D%0A%20%20FR%20--%3E%20SK%5B%22%E6%A8%A1%E5%9E%8B%E5%A4%96%E7%9A%84%E9%80%89%E8%82%A1%E4%B8%8E%E6%97%B6%E6%9C%BA%22%5D%0A%20%20ABS%20--%3E%20ALPHA%5B%22%E5%9B%9B%E5%9B%A0%E5%AD%90%20%CE%B1%22%5D%0A%20%20FEE%20--%3E%20ALPHA%0A%20%20SK%20--%3E%20ALPHA%0A%20%20ALPHA%20--%3E%20TOP%5B%22%E8%B5%A2%E5%AE%B6%E5%9F%BA%E9%87%91%EF%BC%9A%CE%B1%E2%89%880%EF%BC%8C%E7%83%AD%E6%89%8B%E5%9F%BA%E6%9C%AC%E6%B6%88%E5%A4%B1%22%5D%0A%20%20ALPHA%20--%3E%20BOT%5B%22%E8%BE%93%E5%AE%B6%E5%9F%BA%E9%87%91%EF%BC%9A%E8%B4%9F%20%CE%B1%20%E9%A1%BD%E5%9B%BA%EF%BC%8C%E8%B4%B9%E7%94%A8%E6%8C%81%E7%BB%AD%E7%A3%A8%E6%8D%9F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p><span class="marginnote">常见误区：初学者容易把四因子 α 当成对未来收益的预测去买基金。它其实是事后会计——把风格收益从已实现收益里扣掉。α 高可能只是运气，或是承担了模型没写进去的风险；按 α 排名买入，常常恰好买在风格拥挤的顶上。</span></p><h3 id="四因子之后还要不要五因子、质量与-bab" tabindex="-1">四因子之后还要不要五因子、质量与 BAB <a class="header-anchor" href="#四因子之后还要不要五因子、质量与-bab" aria-label="Permalink to &quot;四因子之后还要不要五因子、质量与 BAB&quot;">​</a></h3><p>Fama–French 2015 年的盈利与投资、Asness 等的 QMJ、Frazzini–Pedersen 的 BAB，都会进一步切基金 α。Carhart 四因子不是终点，它是 1997 年能用的、对「热手」最关键的那一块补丁。评价当代基金时，只报四因子 α 而把盈利、投资、低波暴露留在残差里，会重演当年只用三因子的错误。反过来，因子堆得太多，样本内 α 被过度吸收，样本外没有对应的可投资基准。实务折中是：至少包含市场、规模、价值、动量；若基金明确宣称质量或低波，再把对应因子放进右侧，并预先声明。</p><p><span class="marginnote">Carhart 原文的样本是美股共同基金，含存活偏差处理。把四因子套到对冲基金、私募或量化 CTA 上，因子集合本身就不对：CTA 更接近 <a href="/quant/tsmom">时间序列动量</a> 与期限结构，不是个股 PR1YR。基准错了，α 只是风格错配。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>四因子假定 β 恒定。基金换经理、改风格、规模膨胀后的能力衰减，都会让全样本 \\(p_i\\) 变成平均暴露。滚动回归或持仓特征能捕捉时变，但会引入噪声。动量崩溃月里，PR1YR 自身左尾极肥，基金若在崩溃前降低了动量暴露，全样本回归会低估其择时；若没降，α 会在那几个月被因子解释掉，看起来「没有技能地亏了该亏的」。两种叙事要用持仓或时变 β 才能分开，不能只看一个 α 数字。</p><p>不要用四因子 α 给单只基金排名并当成未来收益预测。Carhart 的结论是<strong>分组层面</strong>持续性的消失，不是「α 排序无信息」。费用、容量、风格漂移才是单只基金的一等事实。不要把纸上四因子的 \\(R^2\\) 写成基金经理「解释了多少市场」——\\(R^2\\) 高只说明该基金是风格的线性组合，可能恰恰没有主动性。</p><p>A 股、新兴市场复制时，动量的符号与强度、跳月规则、涨跌停与卖空约束都会改 PR1YR 的含义。应用当地断点重做因子，再用当地基金收益回归。直接下载美股 UMD 去解释 A 股主动基金，是常见的虚假国际比较。</p><p><span class="marginnote">出处是 Carhart, <em>Journal of Finance</em>, 1997。动量现象本身出自 Jegadeesh &amp; Titman, 1993。Ken French 的 MOM/WML 是后续标准化，与 PR1YR 相近但不是同一序列。写「Carhart 四因子」应同时交代动量腿的加权与断点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四因子 = 市场 + SMB + HML + 一年期动量（PR1YR/WML）；直接动机是把风格从基金 α 里拿走。</li><li>股票动量组合的三因子 α 被第四个因子吸收；基金热手在四因子下基本消失，底部负 α 更常留下。</li><li>PR1YR 与 French 的价值加权 UMD 细节不同；复制与评价必须声明口径。</li><li>模型是基准不是技能证明；质量、盈利、低波等后续因子在相关策略上仍应进入右侧。</li><li>β 恒定、样本市场、费用前后，都会改变 α 的读法。</li><li>出处：Carhart, <em>Journal of Finance</em>, 1997；三因子见 Fama &amp; French, 1993；动量见 Jegadeesh &amp; Titman, 1993。</li></ul>',11))])}const P=o(p,[["render",m]]);export{D as __pageData,P as default};
